class Solution {
public:
    int widestFence(vector<int>& planks) {
        int n = planks.size();
        vector<long long> cands;
        for (int x : planks) cands.push_back(x);
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                cands.push_back((long long)planks[i] + planks[j]);
        sort(cands.begin(), cands.end());
        cands.erase(unique(cands.begin(), cands.end()), cands.end());
        int best = 0;
        for (long long H : cands) {
            vector<int> rem;
            int units = 0;
            for (int x : planks) {
                if (x == H) units++;
                else rem.push_back(x);
            }
            sort(rem.begin(), rem.end());
            int i = 0, j = rem.size() - 1;
            while (i < j) {
                long long s = (long long)rem[i] + rem[j];
                if (s == H) { units++; i++; j--; }
                else if (s < H) i++;
                else j--;
            }
            best = max(best, units);
        }
        return best;
    }
};

