class Solution {
    public int widestFence(int[] planks) {
        int n = planks.length;
        java.util.Set<Long> set = new java.util.HashSet<>();
        for (int x : planks) set.add((long) x);
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                set.add((long) planks[i] + planks[j]);
        int best = 0;
        for (long H : set) {
            java.util.List<Integer> rem = new java.util.ArrayList<>();
            int units = 0;
            for (int x : planks) {
                if (x == H) units++;
                else rem.add(x);
            }
            rem.sort(Integer::compareTo);
            int i = 0, j = rem.size() - 1;
            while (i < j) {
                long s = (long) rem.get(i) + rem.get(j);
                if (s == H) { units++; i++; j--; }
                else if (s < H) i++;
                else j--;
            }
            best = Math.max(best, units);
        }
        return best;
    }
}

