from collections import Counter
class Solution:
    def widestFence(self, planks):
        single = Counter(planks)
        pair = Counter()
        n = len(planks)
        for i in range(n):
            for j in range(i + 1, n):
                pair[planks[i] + planks[j]] += 1
        ans = max(single.values())
        for h, c in pair.items():
            ans = max(ans, c + single.get(h, 0))
        return ans

