class Solution {
public:
    int widestFence(vector<int>& planks) {
        unordered_map<long long, int> single, pr;
        int n = planks.size();
        for (int x : planks) single[x]++;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                pr[(long long)planks[i] + planks[j]]++;
        int ans = 0;
        for (auto& p : single) ans = max(ans, p.second);
        for (auto& p : pr) {
            auto it = single.find(p.first);
            ans = max(ans, p.second + (it == single.end() ? 0 : it->second));
        }
        return ans;
    }
};

