class Solution {
    public int widestFence(int[] planks) {
        int n = planks.length;
        java.util.Map<Long, Integer> single = new java.util.HashMap<>();
        java.util.Map<Long, Integer> pair = new java.util.HashMap<>();
        for (int x : planks) single.merge((long) x, 1, Integer::sum);
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                pair.merge((long) planks[i] + planks[j], 1, Integer::sum);
        int ans = 0;
        for (int c : single.values()) ans = Math.max(ans, c);
        for (var e : pair.entrySet())
            ans = Math.max(ans, e.getValue() + single.getOrDefault(e.getKey(), 0));
        return ans;
    }
}

