    const single = new Map(), pair = new Map();
    const n = planks.length;
    for (const x of planks) single.set(x, (single.get(x) || 0) + 1);
    for (let i = 0; i < n; i++)
        for (let j = i + 1; j < n; j++) {
            const s = planks[i] + planks[j];
            pair.set(s, (pair.get(s) || 0) + 1);
        }
    let ans = 0;
    for (const c of single.values()) ans = Math.max(ans, c);
    for (const [h, c] of pair) ans = Math.max(ans, c + (single.get(h) || 0));
    return ans;
};
